B.a4u=new A.L("135","\u0411\u0430 \u0448\u0430\u04b3\u0440 \u0440\u0430\u0444\u0442\u04e3, \u0440\u0430\u0441\u043c\u0438 \u0448\u0430\u04b3\u0440\u0440\u043e \u0433\u0438\u0440.","\u0628\u0647 \u0634\u0647\u0631 \u0631\u0641\u062a\u06cc\u060c \u0631\u0633\u0645 \u0634\u0647\u0631 \u0631\u0627 \u06af\u06cc\u0631.","\u0411\u0430 \u04b7\u043e\u0439\u0438 \u043d\u0430\u0432 \u0440\u0430\u0444\u0442\u04e3, \u049b\u043e\u0438\u0434\u0430 \u0432\u0430 \u0440\u0430\u0441\u043c\u0438 \u043e\u043d \u04b7\u043e\u0440\u043e \u0440\u0438\u043e\u044f \u043a\u0443\u043d.","\u0418\u043d\u0441\u043e\u043d \u0431\u043e\u044f\u0434 \u0431\u0430 \u043c\u0443\u04b3\u0438\u0442\u0438 \u043d\u0430\u0432 \u0431\u043e \u044d\u04b3\u0442\u0438\u0440\u043e\u043c \u043c\u0443\u0442\u043e\u0431\u0438\u049b \u0448\u0430\u0432\u0430\u0434, \u0430\u0433\u0430\u0440 \u043e\u043d \u0431\u0430 \u04ef \u0437\u0430\u0440\u0430\u0440 \u043d\u0430\u0440\u0430\u0441\u043e\u043d\u0430\u0434.","\u0414\u0430\u0440 \u043a\u0438\u0448\u0432\u0430\u0440\u0438 \u0434\u0438\u0433\u0430\u0440 \u049b\u043e\u0438\u0434\u0430\u04b3\u043e\u0438 \u043c\u0430\u04b3\u0430\u043b\u043b\u0438\u0440\u043e \u043e\u043c\u04ef\u0445\u0442; \u0431\u0430 \u0448\u0430\u04b3\u0440 \u0440\u0430\u0444\u0442\u04e3, \u0440\u0430\u0441\u043c\u0438 \u0448\u0430\u04b3\u0440\u0440\u043e \u0433\u0438\u0440.","odob",4,B.k,B.l,u.B,null,B.j)
B.a4b=new A.L("136","\u049a\u0430\u0440\u0493\u0430 \u0431\u0430 \u049b\u0430\u0440\u0493\u0430 \u0447\u0430\u0448\u043c \u043d\u0430\u043c\u0435\u043a\u0430\u043d\u0430\u0434.","\u0642\u0627\u0631\u063a\u0647 \u0628\u0647 \u0642\u0627\u0631\u063a\u0647 \u0686\u0634\u0645 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.","\u049a\u0430\u0440\u0493\u0430 \u0431\u0430 \u049b\u0430\u0440\u0493\u0430\u0438 \u0434\u0438\u0433\u0430\u0440 \u0437\u0430\u0440\u0430\u0440 \u043d\u0430\u043c\u0435\u0440\u0430\u0441\u043e\u043d\u0430\u0434 \u2014 \u0438\u043d \u0442\u0430\u0448\u0431\u0435\u04b3 \u0431\u0430 \u04b3\u0430\u043c\u0434\u0438\u0433\u0430\u0440\u043f\u0443\u0448\u0442\u0438\u0431\u043e\u043d\u0438\u0438 \u0433\u0443\u0440\u04ef\u04b3 \u0430\u0441\u0442.","\u041e\u0434\u0430\u043c\u043e\u043d\u0438 \u044f\u043a \u0433\u0443\u0440\u04ef\u04b3 \u0431\u0430\u044a\u0437\u0430\u043d \u04b3\u0430\u0442\u0442\u043e \u04b3\u0430\u043d\u0433\u043e\u043c\u0438 \u0445\u0430\u0442\u043e \u04b3\u0430\u043c\u0434\u0438\u0433\u0430\u0440\u0440\u043e \u04b3\u0438\u043c\u043e\u044f \u043c\u0435\u043a\u0443\u043d\u0430\u043d\u0434; \u043c\u0430\u049b\u043e\u043b \u0430\u043a\u0441\u0430\u0440 \u0432\u0430\u049b\u0442 \u0431\u043e \u043c\u0430\u044a\u043d\u043e\u0438 \u0442\u0430\u043d\u049b\u0438\u0434\u04e3 \u0438\u0441\u0442\u0438\u0444\u043e\u0434\u0430 \u043c\u0435\u0448\u0430\u0432\u0430\u0434.","\u0414\u0443 \u04b3\u0430\u043c\u043a\u043e\u0440 \u0445\u0430\u0442\u043e\u0438 \u044f\u043a\u0434\u0438\u0433\u0430\u0440\u0440\u043e \u043f\u0438\u043d\u04b3\u043e\u043d \u043a\u0430\u0440\u0434\u0430\u043d\u0434; \u049b\u0430\u0440\u0493\u0430 \u0431\u0430 \u049b\u0430\u0440\u0493\u0430 \u0447\u0430\u0448\u043c \u043d\u0430\u043c\u0435\u043a\u0430\u043d\u0430\u0434.","hikmat",5,B.k,B.l,"\u0417\u0430\u0440\u0431\u0443\u043b\u043c\u0430\u0441\u0430\u043b \u0432\u0430 \u043c\u0430\u049b\u043e\u043b\u04b3\u043e\u0438 \u0442\u043e\u04b7\u0438\u043a\u04e3",null,B.j)
B.a41=new A.L("137","\u0413\u0443\u0440\u0433\u0437\u043e\u0434\u0430 \u043e\u049b\u0438\u0431\u0430\u0442 \u0433\u0443\u0440\u0433 \u0448\u0430\u0432\u0430\u0434.","\u06af\u0631\u06af\u0632\u0627\u062f\u0647 \u0639\u0627\u0642\u0628\u062a \u06af\u0631\u06af \u0634\u0648\u062f.","\u041c\u0430\u049b\u043e\u043b \u043c\u0435\u0433\u04ef\u044f\u0434, \u043a\u0438 \u0442\u0430\u0431\u0438\u0430\u0442\u0438 \u0430\u0441\u043b\u04e3 \u0434\u0435\u0440 \u0451 \u0437\u0443\u0434 \u0445\u0443\u0434\u0440\u043e \u043d\u0438\u0448\u043e\u043d \u043c\u0435\u0434\u0438\u04b3\u0430\u0434.","\u041e\u0434\u0430\u0442 \u0451 \u0445\u0438\u0441\u043b\u0430\u0442\u0438 \u0440\u0435\u0448\u0430\u0434\u043e\u0440\u0440\u043e \u0442\u0430\u043d\u04b3\u043e \u0431\u043e \u043d\u0430\u043c\u0443\u0434\u0438 \u0437\u043e\u04b3\u0438\u0440\u04e3 \u043f\u0438\u043d\u04b3\u043e\u043d \u043a\u0430\u0440\u0434\u0430\u043d \u0434\u0443\u0448\u0432\u043e\u0440 \u0430\u0441\u0442; \u0438\u043d \u043c\u0430\u044a\u043d\u043e\u0438 \u043c\u0430\u04b7\u043e\u0437\u04e3 \u0434\u043e\u0440\u0430\u0434, \u043d\u0430 \u04b3\u0443\u043a\u043c\u0438 \u049b\u0430\u0442\u044a\u04e3 \u0434\u0430\u0440 \u0431\u043e\u0440\u0430\u0438 \u0438\u0440\u0441.","\u04ee \u043c\u0443\u0434\u0434\u0430\u0442\u0435 \u0445\u0443\u0434\u0440\u043e \u043e\u0440\u043e\u043c \u043d\u0438\u0448\u043e\u043d \u0434\u043e\u0434, \u0432\u0430\u043b\u0435 \u0431\u043e\u0437 \u0431\u0430 \u0440\u0430\u0444\u0442\u043e\u0440\u0438 \u043f\u0435\u0448\u0438\u043d\u0430 \u0431\u0430\u0440\u0433\u0430\u0448\u0442; \u0433\u0443\u0440\u0433\u0437\u043e\u0434\u0430 \u043e\u049b\u0438\u0431\u0430\u0442 \u0433\u0443\u0440\u0433 \u0448\u0430\u0432\u0430\u0434.","hikmat",5,B.k,B.l,u.B,null,B.j)
B.a33=new A.L("138","\u0421\u0430\u0433 \u0430\u043a\u043a\u043e\u0441 \u043c\u0435\u0437\u0430\u043d\u0430\u0434, \u043a\u043e\u0440\u0432\u043e\u043d \u043c\u0435\u0433\u0443\u0437\u0430\u0440\u0430\u0434.","\u0633\u06af \u0639\u0642\u0627\u0633 \u0645\u06cc\u200c\u0632\u0646\u062f\u060c \u06a9\u0627\u0631\u0648\u0627\u0646 \u0645\u06cc\u200c\u06af\u0630\u0631\u062f.","\u0421\u0430\u0433 \u0430\u043a\u043a\u043e\u0441 \u043c\u0435\u0437\u0430\u043d\u0430\u0434, \u0432\u0430\u043b\u0435 \u043a\u043e\u0440\u0432\u043e\u043d \u0440\u043e\u04b3\u0438 \u0445\u0443\u0434\u0440\u043e \u0438\u0434\u043e\u043c\u0430 \u043c\u0435\u0434\u0438\u04b3\u0430\u0434.","\u0411\u0430 \u04b3\u0430\u0440 \u0442\u0430\u043d\u049b\u0438\u0434, \u043e\u0432\u043e\u0437\u0430 \u0451 \u0441\u0430\u0434\u043e\u0438 \u0445\u0430\u043b\u0430\u043b\u0440\u0430\u0441\u043e\u043d \u0442\u0430\u0432\u0430\u049b\u049b\u0443\u0444 \u043d\u0430\u043a\u0443\u043d; \u043a\u043e\u0440\u0438 \u043c\u0443\u04b3\u0438\u043c\u0440\u043e \u0438\u0434\u043e\u043c\u0430 \u0434\u0435\u04b3.","\u0411\u043e \u0432\u0443\u04b7\u0443\u0434\u0438 \u043c\u0430\u0441\u0445\u0430\u0440\u0430\u0438 \u0434\u0438\u0433\u0430\u0440\u043e\u043d \u04ef \u0442\u0430\u04b3\u0441\u0438\u043b\u0440\u043e \u0434\u0430\u0432\u043e\u043c \u0434\u043e\u0434; \u0441\u0430\u0433 \u0430\u043a\u043a\u043e\u0441 \u043c\u0435\u0437\u0430\u043d\u0430\u0434, \u043a\u043e\u0440\u0432\u043e\u043d \u043c\u0435\u0433\u0443\u0437\u0430\u0440\u0430\u0434.","hikmat",6,B.k,B.l,u.B,null,B.j)
B.a4m=new A.L("139","\u0421\u0430\u0433\u0438 \u0430\u043a\u043a\u043e\u0441\u0430\u043a \u0433\u0430\u0437\u0430\u043d\u0434\u0430 \u043d\u0435\u0441\u0442.","\u0633\u06af \u0639\u0642\u0627\u0633\u06a9 \u06af\u0632\u0646\u062f\u0647 \u0646\u06cc\u0633\u062a.","\u0421\u0430\u0433\u0435, \u043a\u0438 \u0431\u0438\u0441\u0451\u0440 \u0430\u043a\u043a\u043e\u0441 \u043c\u0435\u0437\u0430\u043d\u0430\u0434, \u043e\u0434\u0430\u0442\u0430\u043d \u043a\u0430\u043c\u0442\u0430\u0440 \u0433\u0430\u0437\u0438\u0434\u0430\u043d\u04e3 \u0430\u0441\u0442 \u2014 \u043c\u0430\u044a\u043d\u043e\u0438 \u043c\u0430\u04b7\u043e\u0437\u04e3.","\u041a\u0430\u0441\u0435, \u043a\u0438 \u0431\u0438\u0441\u0451\u0440 \u0442\u0430\u04b3\u0434\u0438\u0434 \u043c\u0435\u043a\u0443\u043d\u0430\u0434, \u043d\u0430 \u04b3\u0430\u043c\u0435\u0448\u0430 \u0445\u0430\u0442\u0430\u0440\u043d\u043e\u043a\u0442\u0430\u0440\u0438\u043d \u0430\u0441\u0442; \u0441\u0443\u0445\u0430\u043d\u0438 \u0431\u0430\u043b\u0430\u043d\u0434 \u04b3\u0430\u0442\u043c\u0430\u043d \u0430\u043c\u0430\u043b\u0438 \u0441\u0430\u0445\u0442 \u043d\u0435\u0441\u0442.","\u04ee \u0431\u0438\u0441\u0451\u0440 \u0442\u0430\u04b3\u0434\u0438\u0434 \u043c\u0435\u043a\u0430\u0440\u0434, \u0432\u0430\u043b\u0435 \u043a\u043e\u0440\u0435 \u043d\u0430\u043c\u0435\u043a\u0430\u0440\u0434; \u0441\u0430\u0433\u0438 \u0430\u043a\u043a\u043e\u0441\u0430\u043a \u0433\u0430\u0437\u0430\u043d\u0434\u0430 \u043d\u0435\u0441\u0442.","hikmat",5,B.k,B.l,"\u0417\u0430\u0440\u0431\u0443\u043b\u043c\u0430\u0441\u0430\u043b \u0432\u0430 \u043c\u0430\u049b\u043e\u043b\u04b3\u043e\u0438 \u0442\u043e\u04b7\u0438\u043a\u04e3",null,B.j)
B.a3A=new A.L("140","\u0410\u0437 \u0430\u0441\u043f \u0430\u0444\u0442\u04e3, \u0430\u0437 \u0430\u0441\u043b \u043d\u0430\u0430\u0444\u0442.","\u0627\u0632 \u0627\u0633\u067e \u0627\u0641\u062a\u06cc\u060c \u0627\u0632 \u0627\u0635\u0644 \u0646\u06cc\u0641\u062a.","\u0410\u0433\u0430\u0440 \u043c\u043e\u043b\u0443 \u043c\u0430\u049b\u043e\u043c \u0451 \u043c\u0443\u0432\u0430\u0444\u0444\u0430\u049b\u0438\u044f\u0442\u0440\u043e \u0430\u0437 \u0434\u0430\u0441\u0442 \u0434\u0438\u04b3\u04e3, \u0430\u0441\u043b\u0438 \u0438\u043d\u0441\u043e\u043d\u04e3 \u0432\u0430 \u0438\u0437\u0437\u0430\u0442\u0438 \u0445\u0443\u0434\u0440\u043e \u0430\u0437 \u0434\u0430\u0441\u0442 \u043d\u0430\u0434\u0435\u04b3.","\u041d\u043e\u043a\u043e\u043c\u04e3 \u043d\u0430\u0431\u043e\u044f\u0434 \u0441\u0430\u0431\u0430\u0431 \u0448\u0430\u0432\u0430\u0434, \u043a\u0438 \u0438\u043d\u0441\u043e\u043d \u0430\u0440\u0437\u0438\u0448\u04b3\u043e, \u0448\u0430\u0440\u0430\u0444 \u0451 \u0445\u0443\u0434\u0448\u0438\u043d\u043e\u0441\u0438\u0430\u0448\u0440\u043e \u0444\u0430\u0440\u043e\u043c\u04ef\u0448 \u043a\u0443\u043d\u0430\u0434.","\u041a\u043e\u0440\u0430\u0448\u0440\u043e \u0430\u0437 \u0434\u0430\u0441\u0442 \u0434\u043e\u0434, \u0432\u0430\u043b\u0435 \u0440\u043e\u0441\u0442\u049b\u0430\u0432\u043b\u0438\u0430\u0448\u0440\u043e \u043d\u0435; \u0430\u0437 \u0430\u0441\u043f \u0430\u0444\u0442\u04e3, \u0430\u0437 \u0430\u0441\u043b \u043d\u0430\u0430\u0444\u0442.","jasorat",5,B.k,B.l,u.B,null,B.j)
